import { Component } from '@angular/core';
import { IonicPage, MenuController, NavController, Platform } from 'ionic-angular';
import { TranslateService } from '@ngx-translate/core';
import { ImpostazioneProvider } from "../../providers/impostazione/impostazione";

//import { Storage } from '@ionic/storage';

export interface Slide {
    title: string;
    description: string;
    image: string;
}

@IonicPage()
@Component({
    selector: 'page-tutorial',
    templateUrl: 'tutorial.html'
})

export class TutorialPage {
    slides: Slide[];
    showSkip = true;
    dir: string = 'ltr';

    constructor(
        private readonly impostazioneProvider: ImpostazioneProvider,
        public navCtrl: NavController, 
        public menu: MenuController, 
        translate: TranslateService, 
        public platform: Platform,
        //public storage: Storage
        ) {
        
        this.dir = platform.dir();
        translate.get(["TUTORIAL_SLIDE1_TITLE",
            "TUTORIAL_SLIDE1_DESCRIPTION",
            "TUTORIAL_SLIDE2_TITLE",
            "TUTORIAL_SLIDE2_DESCRIPTION",
            "TUTORIAL_SLIDE3_TITLE",
            "TUTORIAL_SLIDE3_DESCRIPTION",
        ]).subscribe(
            (values) => {
                this.slides = [{
                    title: values.TUTORIAL_SLIDE1_TITLE,
                    description: values.TUTORIAL_SLIDE1_DESCRIPTION,
                    image: 'assets/img/ica-slidebox-img-1.png',
                },{
                    title: values.TUTORIAL_SLIDE2_TITLE,
                    description: values.TUTORIAL_SLIDE2_DESCRIPTION,
                    image: 'assets/img/ica-slidebox-img-2.png',
                },{
                    title: values.TUTORIAL_SLIDE3_TITLE,
                    description: values.TUTORIAL_SLIDE3_DESCRIPTION,
                    image: 'assets/img/ica-slidebox-img-3.png',
                }
            ];
        });
    }

    startApp() {
        //this.storage.get('_settings').then((resp) => {
            this.impostazioneProvider.initProvider().then(() => this.impostazioneProvider.filter()
                .then((settings) => {
                        var count = 0;
                        for (let el in settings) {
                            let row = settings[el];
                            count++;
                            //console.log(row)
                            break;
                        }
                        if(count){
                            this.navCtrl.setRoot('WelcomePage', {}, { animate: true, direction: 'forward' });
                        }else{
                            this.navCtrl.setRoot('ImpostazioniPage', {}, { animate: true, direction: 'forward' });
                        }
                    }
                )
            )
            
            

            // if(resp !== null){
            //     if(resp.option1){
            //         console.log("comune/zona impostato, vai a welcome",resp.option1)
            //         this.navCtrl.setRoot('WelcomePage', {}, { animate: true, direction: 'forward' });
            //     }else{
            //         console.log("comune/zona non impostato, vai a settings",resp.option1)
            //         this.navCtrl.setRoot('SettingsPage', {}, { animate: true, direction: 'forward' });
            //     }
            // }else{
            //     this.navCtrl.setRoot('SettingsPage', {}, { animate: true, direction: 'forward' });
            // }
        //});            
    }

    onSlideChangeStart(slider) {
        this.showSkip = !slider.isEnd();
    }

    ionViewDidEnter() {
        // the root left menu should be disabled on the tutorial page
        this.menu.enable(false);
    }

    ionViewWillLeave() {
        // enable the root left menu when leaving the tutorial page
        this.menu.enable(true);
    }
}



